tool_input.command:
cd /app && find /proc -maxdepth 2 -name cmdline 2>/dev/null -exec grep -l qemu {} \; 2>/dev/null | sed 's|/proc/\([0-9]*\)/.*|\1|' | sort -u | xargs -r kill -9 2>/dev/null; sleep 2; rm -f qemu.log && /usr/bin/expect << 'EXPECT_SCRIPT'
set timeout 180
set send_slow {1 0.05}

spawn qemu-system-x86_64 -m 2048 -cdrom /app/alpine.iso -net nic -net user -nographic

expect {
  "boot: " {
    send -s "boot\r"
    exp_continue
  }
  "localhost login: " {
    send -s "root\r"
    expect "~ # "
    send -s "apk update \&\& apk add openssh\r"
    expect "~ # "
    send -s "sed -i 's/^#PermitRootLogin.*/PermitRootLogin yes/' /etc/ssh/sshd_config\r"
    expect "~ # "
    send -s "echo 'root:password123' | chpasswd\r"
    expect "~ # "
    send -s "/etc/init.d/sshd start\r"
    expect "~ # "
    send -s "while true; do sleep 10; done\r"
    interact
  }
  timeout {
    puts "Timeout waiting for boot"
    exit 1
  }
}
EXPECT_SCRIPT
